#!/usr/bin/env python3
"""将二进制镜像文件转换为纯 C 只读字节数组源码（跨平台构建内嵌 ELF）。"""

import argparse
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description="Convert binary file to C array")
    parser.add_argument("--symbol", required=True, help="C array symbol base name")
    parser.add_argument("input", type=Path, help="Input binary path")
    parser.add_argument("output", type=Path, help="Output C source path")
    args = parser.parse_args()

    data = args.input.read_bytes()
    args.output.parent.mkdir(parents=True, exist_ok=True)

    lines = [
        "/* Auto-generated by scripts/bin2c.py - do not edit manually. */",
        "#include <stddef.h>",
        "#include <stdint.h>",
        "",
        f"const uint8_t {args.symbol}[] = {{",
    ]
    for offset in range(0, len(data), 16):
        chunk = data[offset:offset + 16]
        hex_vals = ", ".join(f"0x{b:02x}U" for b in chunk)
        lines.append(f"    {hex_vals},")
    lines.extend([
        "};",
        "",
        f"const size_t {args.symbol}_size = sizeof({args.symbol});",
        "",
    ])
    args.output.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
